    /**
     * email_settingsActions::executeUpdateEmailSettings.     
     * @return void retorna la vista asociada a este actions
    */
    public function executeUpdateEmailSettings()
    {
        $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
        if(!$this->tienePrivilegio('email_settings/create')){
            $this->getUser()->setFlash('message_error', 'Ocurrio un error, la funcionalidad esta restringida por privilegios de administrador');
            $this->forward('email_settings', 'create');
        }
        //***********************************************************************************************
        $emailproviderconfig_id = trim($this->getRequestParameter('emailproviderconfig_id')) ?  trim($this->getRequestParameter('emailproviderconfig_id')) : null;
        $emailprovider_id = trim($this->getRequestParameter('emailprovider_id')) ?  trim($this->getRequestParameter('emailprovider_id')) : null;
        $server_name = trim($this->getRequestParameter('server_name')) ?  trim($this->getRequestParameter('server_name')) : null;
        $listen_puerto = trim($this->getRequestParameter('listen_puerto')) ?  trim($this->getRequestParameter('listen_puerto')) : null;
        $type_encryption = trim($this->getRequestParameter('type_encryption')) ?  strtolower(trim($this->getRequestParameter('type_encryption'))) : null;
        $tenant_name = trim($this->getRequestParameter('tenant_name')) ?  trim($this->getRequestParameter('tenant_name')) : null;
        $oauth2_client = trim($this->getRequestParameter('oauth2_client')) ?  trim($this->getRequestParameter('oauth2_client')) : null;
        $oauth2_secret = trim($this->getRequestParameter('oauth2_secret')) ?  SED::encryption(trim($this->getRequestParameter('oauth2_secret'))) : null;
        $oauth2_redirect_uri = trim($this->getRequestParameter('oauth2_redirect_uri')) ?  trim($this->getRequestParameter('oauth2_redirect_uri')) : null;
        //***********************************************************************************************
        if(empty($emailprovider_id) || empty($server_name) || empty($listen_puerto) || empty($type_encryption)){
            $this->getUser()->setFlash('message_error', 'Ocurrio un error, los parametros enviados no son validos o algunos no se encuentran');
            $this->forward('email_settings', 'create');
        }
        //***********************************************************************************************
        if(!empty($tenant_name) || !empty($oauth2_client)){
            if(empty($oauth2_secret) || empty($oauth2_redirect_uri) ){
                $this->getUser()->setFlash('message_error', 'Ocurrio un error, los parametros Secret ID y Redirect URI son obligatorios');
                $this->forward('email_settings', 'create');
            }
        }
        //***********************************************************************************************
        $email_settings = new EmailProviderConfig();
        $email_settings->setServerName($server_name);
        $email_settings->setTenantName($tenant_name);
        $email_settings->setListenPuerto($listen_puerto);
        $email_settings->setOauth2Client($oauth2_client);
        $email_settings->setOauth2Secret($oauth2_secret);
        $email_settings->setOauth2RedirectUri($oauth2_redirect_uri);
        $email_settings->setTypeEncryption($type_encryption);
        $email_settings->setEmailproviderId($emailprovider_id);
        $email_settings->setFechaCreacion(date('Y-m-d G:i:s'));
        $email_settings->setFechaModificacion(date('Y-m-d G:i:s'));
        $email_settings->save();
        //***********************************************************************************************
        AuditLogPeer::guardarAuditoriaLite(EmailProviderConfigPeer::getOMClass(),new EmailProviderConfig(), $email_settings ,
            ModulesEnable::Seguridad,$email_settings->getPrimaryKey());
        //***********************************************************************************************
        $this->getUser()->setFlash('message_success', 'Registro creado exitosamente');
        return $this->redirect($this->getRequest()->getScriptName() . '/email_settings/show?emailproviderconfig_id=' . $email_settings->getPrimaryKey());
    }

